"""Independent, deliberately naive reference implementation of PROTOCOL.md.

Used only for differential testing: O(backlog) lag updates, O(backlog) rank
errors and deepcopy checkpoints.  It is written straight from the prose so a
disagreement with the fast engine means one of them mis-reads the protocol.
"""
import copy
from bisect import bisect_right


class Ref:
    def __init__(self, spec):
        self.M = spec['banks']
        self.L = spec['load_balancers']
        self.fifo_cap = spec['fifo_bytes']
        self.pifo_cap = spec['pifo_bytes']
        self.batch = spec['refill_batch']
        self.P = spec['sample_period']
        self.borders = list(spec['borders'])
        self.R = len(self.borders) - 1
        self.U = self.borders[-1]
        self.C = [[[(1 if q < (r % self.M) else 0) for r in range(self.R)]
                   for q in range(self.M)] for _ in range(self.L)]
        self.H = [0] * self.R
        self.t = 0
        self.p = 0
        self.l = 0
        self.a = 0
        self.fifo = [[] for _ in range(self.M)]      # ordinals, arrival order
        self.pifo = [[] for _ in range(self.M)]      # ordinals, (rank, ord) order
        self.fbytes = [0] * self.M
        self.pbytes = [0] * self.M
        self.pk = {}                                 # ordinal -> record dict
        pol = spec['policy']
        self.kind = pol['kind']
        self.levels = {f: v for f, v in pol.get('levels', [])}
        self.weights = {f: v for f, v in pol.get('weights', [])}
        self.finish = {f: 0 for f in self.weights}
        self.ftime = 0
        self.V = 0
        self.saves = {}
        self.log = []

    # -- policy ---------------------------------------------------------
    def rank_of(self, flow, length, flow_size):
        if self.kind == 'fifo':
            self.ftime += 1
            return self.ftime
        if self.kind == 'sp':
            return self.levels[flow]
        if self.kind == 'sff':
            return flow_size
        tag = max(self.finish[flow], self.V) + -(-(length * 1048576) // self.weights[flow])
        self.finish[flow] = tag
        return tag

    def post_service(self, rank):
        if self.kind == 'wfq' and rank > self.V:
            self.V = rank

    # -- helpers --------------------------------------------------------
    def classify(self, rank):
        x = min(rank, self.U - 1)
        return bisect_right(self.borders, x) - 1

    def live_items(self):
        return self.pk.values()

    def lag_of(self, ordinal):
        return self.pk[ordinal]['lag']

    # -- commands -------------------------------------------------------
    def enqueue(self, i, pid, flow, length, flow_size):
        rank = self.rank_of(flow, length, flow_size)
        r = self.classify(rank)
        l = self.l
        self.l = (l + 1) % self.L
        best = None
        q = 0
        for cand in range(self.M):
            value = self.C[l][cand][r]
            if best is None or value < best:
                best = value
                q = cand
        accepted = self.fbytes[q] + length <= self.fifo_cap
        if accepted:
            self.C[l][q][r] += 1
            self.a += 1
            self.pk[i] = {'rank': rank, 'len': length, 'flow': flow, 'id': pid,
                          'stage': 'fifo', 'bank': q, 'lag': 0}
            self.fifo[q].append(i)
            self.fbytes[q] += length
        self.log.append([i, 'enqueue', pid, rank, l, r, q, accepted])
        if accepted and self.a == self.P:
            self.sample(i)

    def sample(self, i):
        X = [0] * self.R
        for l in range(self.L):
            for q in range(self.M):
                for r in range(self.R):
                    X[r] += self.C[l][q][r]
        for l in range(self.L):
            for r in range(self.R):
                low = min(self.C[l][q][r] for q in range(self.M))
                for q in range(self.M):
                    self.C[l][q][r] -= low
        self.H = [self.H[r] // 2 + X[r] for r in range(self.R)]
        self.a = 0
        self.log.append([i, 'sample', X, list(self.H)])

    def sort_key(self, ordinal):
        return (self.pk[ordinal]['rank'], ordinal)

    def refill(self, q, evicted):
        take = min(self.batch, len(self.fifo[q]))
        moved = self.fifo[q][:take]
        del self.fifo[q][:take]
        for ordinal in moved:
            rec = self.pk[ordinal]
            rec['stage'] = 'pifo'
            self.fbytes[q] -= rec['len']
            self.pbytes[q] += rec['len']
        candidates = self.pifo[q] + moved
        candidates.sort(key=self.sort_key)
        total = self.pbytes[q]
        keep = 0
        running = 0
        for ordinal in candidates:
            if running + self.pk[ordinal]['len'] <= self.pifo_cap:
                running += self.pk[ordinal]['len']
                keep += 1
            else:
                break
        # longest prefix that fits
        kept = candidates[:keep]
        drop = candidates[keep:]
        self.pifo[q] = kept
        self.pbytes[q] = running
        for ordinal in sorted(drop, key=self.sort_key, reverse=True):
            rec = self.pk[ordinal]
            rec['stage'] = 'dead'
            evicted.append(rec['id'])
            del self.pk[ordinal]

    def dequeue(self, i, n):
        for _ in range(n):
            self.visit(i)

    def visit(self, i):
        q = self.p
        self.p = (self.p + 1) % self.M
        old_t = self.t
        self.t += 1
        evicted = []
        was_empty = not self.pifo[q]
        if was_empty:
            self.refill(q, evicted)
        if not self.pifo[q]:
            self.log.append([i, 'dequeue', old_t, q, None, None, 0, 0, evicted])
            return
        ordinal = self.pifo[q].pop(0)
        rec = self.pk[ordinal]
        rank = rec['rank']
        self.pbytes[q] -= rec['len']
        self.post_service(rank)
        if not was_empty:
            self.refill(q, evicted)
        rank_error = sum(1 for other in self.pk.values()
                         if other['rank'] < rank)
        lag = rec['lag']
        del self.pk[ordinal]
        for other in self.pk.values():
            if other['rank'] < rank:
                other['lag'] += 1
        self.log.append([i, 'dequeue', old_t, q, rec['id'], rank, rank_error, lag, evicted])

    def repartition(self, i, new_borders):
        old = self.borders
        told = self.R
        new = list(new_borders)
        tnew = len(new) - 1

        def project(vec):
            out = [0] * tnew
            for r in range(told):
                m = vec[r]
                if m == 0:
                    continue
                b, c = old[r], old[r + 1]
                w = c - b
                for j in range(tnew):
                    u, v = new[j], new[j + 1]
                    lo = min(max(b, u), c) - b
                    hi = min(max(b, v), c) - b
                    out[j] += (m * hi) // w - (m * lo) // w
            return out

        self.C = [[[project(self.C[l][q])[r] for r in range(tnew)]
                   for q in range(self.M)] for l in range(self.L)]
        self.H = project(self.H)
        self.borders = new
        self.R = tnew
        self.U = new[-1]
        self.log.append([i, 'repartition', tnew])

    def cancel(self, i, pid):
        ordinal = self.by_id.get(pid)
        if ordinal is None or ordinal not in self.pk:
            self.log.append([i, 'cancel', pid, None, None, None])
            return
        rec = self.pk[ordinal]
        stage, bank = rec['stage'], rec['bank']
        if stage == 'fifo':
            self.fifo[bank].remove(ordinal)
            self.fbytes[bank] -= rec['len']
        else:
            self.pifo[bank].remove(ordinal)
            self.pbytes[bank] -= rec['len']
        lag = rec['lag']
        del self.pk[ordinal]
        self.log.append([i, 'cancel', pid, stage, bank, lag])

    def inspect(self, i, pid):
        ordinal = self.by_id.get(pid)
        if ordinal is None or ordinal not in self.pk:
            self.log.append([i, 'inspect', pid, None])
            return
        rec = self.pk[ordinal]
        self.log.append([i, 'inspect', pid,
                         [rec['rank'], rec['bank'], rec['stage'], rec['len'],
                          rec['flow'], rec['lag']]])

    def weight(self, i, flow, new_weight):
        if self.kind == 'wfq':
            self.weights[flow] = new_weight
        self.log.append([i, 'weight', flow, new_weight])

    def bundle(self):
        return {'M': self.M, 'L': self.L, 'fifo_cap': self.fifo_cap,
                'pifo_cap': self.pifo_cap, 'batch': self.batch, 'P': self.P,
                'borders': self.borders, 'R': self.R, 'U': self.U, 'C': self.C,
                'H': self.H, 't': self.t, 'p': self.p, 'l': self.l, 'a': self.a,
                'fifo': self.fifo, 'pifo': self.pifo, 'fbytes': self.fbytes,
                'pbytes': self.pbytes, 'pk': self.pk, 'kind': self.kind,
                'levels': self.levels, 'weights': self.weights,
                'finish': self.finish, 'ftime': self.ftime, 'V': self.V}

    def apply(self, state):
        for key, value in state.items():
            setattr(self, key, value)

    def save(self, i, name):
        self.saves[name] = copy.deepcopy(self.bundle())
        self.log.append([i, 'save', name])

    def restore(self, i, name):
        self.apply(copy.deepcopy(self.saves[name]))
        self.log.append([i, 'restore', name])

    # -- driver ---------------------------------------------------------
    def execute(self, events):
        self.by_id = {}
        for i, ev in enumerate(events):
            if ev[0] == 'enqueue':
                self.by_id[ev[1]] = i
        for i, ev in enumerate(events):
            kind = ev[0]
            if kind == 'enqueue':
                self.enqueue(i, ev[1], ev[2], ev[3], ev[4])
            elif kind == 'dequeue':
                self.dequeue(i, ev[1])
            elif kind == 'sample':
                self.sample(i)
            elif kind == 'repartition':
                self.repartition(i, ev[1])
            elif kind == 'cancel':
                self.cancel(i, ev[1])
            elif kind == 'inspect':
                self.inspect(i, ev[1])
            elif kind == 'weight':
                self.weight(i, ev[1], ev[2])
            elif kind == 'save':
                self.save(i, ev[1])
            elif kind == 'restore':
                self.restore(i, ev[1])
            else:
                raise ValueError(kind)
        return {'log': self.log, 'state': self.state()}

    def state(self):
        queues = []
        for q in range(self.M):
            fifo_ids = [self.pk[o]['id'] for o in self.fifo[q] if o in self.pk]
            pifo_ids = [self.pk[o]['id'] for o in
                        sorted(self.pifo[q], key=self.sort_key) if o in self.pk]
            queues.append({'fifo': fifo_ids, 'pifo': pifo_ids,
                           'fifo_bytes': self.fbytes[q],
                           'pifo_bytes': self.pbytes[q]})
        lags = sorted(([rec['id'], rec['lag']] for rec in self.pk.values()),
                      key=lambda item: item[0])
        if self.kind == 'fifo':
            policy = {'kind': 'fifo', 'time': self.ftime}
        elif self.kind == 'sp':
            policy = {'kind': 'sp', 'levels': [[f, self.levels[f]]
                                               for f in sorted(self.levels)]}
        elif self.kind == 'sff':
            policy = {'kind': 'sff'}
        else:
            policy = {'kind': 'wfq', 'virtual_time': self.V,
                      'weights': [[f, self.weights[f]] for f in sorted(self.weights)],
                      'finish': [[f, self.finish[f]] for f in sorted(self.finish)]}
        return {'tick': self.t, 'load_balancer': self.l, 'service_bank': self.p,
                'sample_progress': self.a, 'borders': list(self.borders),
                'counters': [[[self.C[l][q][r] for r in range(self.R)]
                              for q in range(self.M)] for l in range(self.L)],
                'history': list(self.H), 'policy': policy, 'queues': queues,
                'lags': lags}


def run_batch(request):
    return {'runs': [Ref(spec).execute(spec['events']) for spec in request['runs']]}
